typedef enum { ROLE_VIEWER = 1u<<0, ROLE_EDITOR = 1u<<1, ROLE_PAUSER = 1u<<2, ROLE_ADMIN = 1u<<3 } role_t;

/* single decision point: every rule lives here */
int rbac_allow(unsigned subject_roles, unsigned required, unsigned denied) {
    if (subject_roles == 0) return 0;                 /* deny by default  */
    if (subject_roles & denied) return 0;             /* SoD exclusion    */
    return (subject_roles & required) == required;
}

if (!rbac_allow(session->roles, ROLE_PAUSER, ROLE_ADMIN)) return respond_403(req);
